metadata.content:
[
  {
    "name": "卫青",
    "description": "北疆长城守将，全片主角，肩负守城使命",
    "appearance": "38岁，身形魁梧挺拔，古铜肤色，浓眉深目，颧骨高耸，下颌线条如刀削，左眉尾有一道斜长疤痕，目光沉毅",
    "costume": "玄铁色鳞甲战袍，内衬暗红色战袍领口，肩披黑色兽皮披风，腰悬青铜长剑，脚蹬黑皮战靴，束发银冠",
    "personality": "沉稳果决、爱兵如子、外冷内热，深处大义与私情的撕裂"
  },
  {
    "name": "老兵赵勇",
    "description": "跟隨卫青二十年的老兵，忠诚老卒",
    "appearance": "52岁，饱经风霜的黝黑面庞，左眼失明佩戴黑色眼罩，络腮花白胡须，手臂粗壮布满旧伤",
    "costume": "破旧皮甲外罩灰色粗布战袍，无披风，腰别短刀，缠头麻布",
    "personality": "沉默寡言、视死如归，是卫青最信任的兄长式人物"
  },
  {
    "name": "北境蛮族首领呼延烈",
    "description": "北境狼族大单于，本集仅以剪影与背影出现",
    "appearance": "身形如巨熊，肩披厚重狼皮，散发编辫，金属面罩遮住半张脸",
    "costume": "黑色皮甲镶铁钉，肩扛巨型狼牙棒，腰挂弯刀",
    "personality": "残暴、狡黠、视长城以南为猎物"
  },
  {
    "name": "青年士兵小满",
    "description": "初上战场的新兵，象征希望与传承",
    "appearance": "18岁，稚嫩清秀的面庞，单眼皮小眼睛，虎头虎脑",
    "costume": "略显宽大的新制皮甲，红色头巾，无实战经验痕迹",
    "personality": "热血但紧张，从恐惧到成长的弧光"
  }
]

[
  {
    "name": "北疆长城·烽火台",
    "description": "建置场景，长城制高点的瞭望与警戒之所",
    "visualStyle": "晨雾未散，灰色天幕下长城如灰色巨龙蜿蜒，烽火台石墙斑驳，风声凌厉，16:9横构图强调城墙的水平延展"
  },
  {
    "name": "北疆长城·将军营帐",
    "description": "卫青议事之所，悬挂羊皮地图",
    "visualStyle": "昏黄油灯照明，羊皮地图与青铜兵器反射冷光，帐外透进一线青灰天光，整体肃杀压抑"
  },
  {
    "name": "北疆长城·校场",
    "description": "战前集结的列队场地",
    "visualStyle": "黄昏逆光，漫天黄沙扬尘，黑色军阵如铁流，16:9构图展现万军列阵的横向壮阔"
  },
  {
    "name": "北疆长城·城墙主防线",
    "description": "最终决战之地",
    "visualStyle": "夜色将至，烽火台火光冲天映红半边天际，箭矢如雨，城下黑影如潮，浓烟翻滚遮蔽天光"
  }
]

{
  "scenes": [
    {
      "location": "北疆长城·烽火台",
      "time": "黎明前·天色未明",
      "characters": [
        "卫青",
        "赵勇"
      ],
      "action": "卫青登上烽火台极目远眺，赵勇单膝跪地汇报军情。远处地平线狼烟突起，卫青剑眉紧锁。",
      "dialogue": "卫青：敌从何方？几路来犯？\\n赵勇：禀将军，狼烟三起，自西北而来，乌压压一片，怕是不下三万铁骑。",
      "mood": "压抑、肃杀、危机迫近"
    },
    {
      "location": "北疆长城·将军营帐",
      "time": "黎明前·天色微曦",
      "characters": [
        "卫青",
        "赵勇"
      ],
      "action": "卫青走入营帐，凝视羊皮地图，伸手按在长城关隘处。灯火摇曳映出他铁青的脸色，他拔出令旗递给赵勇。",
      "dialogue": "卫青：传我军令，全军集结，死守城垣，无令不得后退半步。\\n赵勇：得令！",
      "mood": "凝重、决绝"
    },
    {
      "location": "北疆长城·校场",
      "time": "清晨·天色灰白",
      "characters": [
        "赵勇",
        "小满",
        "群演士兵"
      ],
      "action": "赵勇在校场高台宣读军令，千军列阵沉默如山。小满在人群中紧张地攥紧长矛，赵勇走到他面前拍了拍他的肩膀。",
      "dialogue": "赵勇：弟兄们，将军有令——人在城在，人亡城亡！\\n赵勇（小声对小满）：小子，怕不怕？\\n小满：不、不怕！",
      "mood": "悲壮、压抑中透出热血"
    },
    {
      "location": "北疆长城·城墙主防线",
      "time": "黄昏·暮色将至",
      "characters": [
        "卫青",
        "赵勇",
        "小满"
      ],
      "action": "卫青率众登上城墙，远方北境蛮族大军如黑潮涌来，战鼓擂动，地动山摇。卫青拔出青铜长剑，剑身反射烽火光芒。",
      "dialogue": "卫青：弟兄们，随我——守土！\\n（旁白/字幕）：长城万里，今夜有我。",
      "mood": "苍凉、悲壮、慷慨赴死"
    }
  ]
}
